const P = '/home/user/uptal-workroom/prototypes'
const SCR = '/tmp/claude-0/-home-user-uptal-workroom/6ab62c15-85ac-5672-9c3c-c0e707cd596b/scratchpad/ob6'
const BRIEF = `You are working on the Uptal Auto-Apply v6 multi-market prototype. Read these first, fully:
${P}/build/ONBOARDING-SPEC.md (your task), ${P}/build/DESIGN.md, ${P}/build/markets/PACK-SPEC.md, ${P}/build/js/engine.js, ${P}/build/i18n/GLOSSARY.md, ${P}/build/build.py.
Source: ${P}/src/v5.html (1.9MB single file; read the screens you own with offset/limit; some lines are huge — use Bash sed/cut/grep for those). Earlier multi-region prototype: ${P}/src/onboarding-multi-region.html.
You OWN these screens and their JS: welcome, where (new), targets, wall, payOtp, checkout, subDone, rights (new), profile, aboutYou, tune (new), blocklist, autopilot, live. Other agents are concurrently (a) tokenizing the dictionary values (T.en/T.ar) of ALL keys, including keys on your screens — so never edit existing dictionary strings in the source and never rely on their exact English text; create new keys (prefix ob6) for new or changed copy, and (b) researching market packs into ${P}/build/markets/packs/XX.core.json (they appear over time; read whatever exists; NEVER write into markets/packs). Market-specific values in your new copy must use tokens ({@ctry.s}, {@$:399}...) or MKT.* calls, never literals. Your outputs: ${P}/build/patches/50-onboarding.json, ${P}/build/js/50-onboarding.js, ${P}/build/css/50-onboarding.css, and merged additions to ${P}/build/i18n/newkeys-{en,gulf,neutral,fr}.json.
Build to YOUR OWN output file only: cd ${P}/build && python3 -I tools/make_personas.py && python3 -I build.py --out ${SCR}/v6-ob.html (create ${SCR} first). Test with Playwright (node; require('/opt/node22/lib/node_modules/playwright'); chromium.launch(); never install browsers): open file://${SCR}/v6-ob.html?persona=<ID>, use go('<screen>') / clicks / the #lang buttons. Screenshots into ${SCR}/shots/ and LOOK at them with Read.`
phase('Build')
const built = await agent(`${BRIEF}\n\nYou are the BUILDER. Implement the full spec end to end. Work incrementally: get the build green and the KSA flow identical-looking to v5 where the spec says keep, then add where/rights/tune, then checkout generalisation, then the profile tailoring. Walk the whole flow for personas SA, AE, US, GB, DE, EG, MA, X-EG-GCC, X-IN-GCC in EN, AR and FR (FR dictionary may still be sparse: fallback to EN is expected for old keys, but YOUR new keys must exist in all four newkeys files). Zero page errors from your code. Return: what you built, screens/flow, data you read from packs (field names), open issues.`, { label: 'build-onboarding', phase: 'Build' })
phase('Review')
const RS = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: { severity: { type: 'string', enum: ['blocker', 'major', 'minor'] }, where: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['severity', 'where', 'problem', 'fix'] } } }, required: ['findings'] }
const reviews = await parallel([
  () => agent(`${BRIEF}\n\nBuilder report:\n${built}\n\nREVIEWER 1 — spec + UX. Build to ${SCR}/rev1.html (use --out). Walk every persona flow from welcome to live in EN and AR. Check against ONBOARDING-SPEC: exactly 2 steps before the paywall (where, roles); nothing else asked pre-payment; residence vs target logic (price/payment from residence, jobs/rights from target); paywall feed uses target employers; checkout methods/tax/renewal per residence; post-payment order rights → profile → aboutYou → tune → blocklist → autopilot → live; auto-answered work rights for citizens; US sponsorship + EEO; sensitive-field rules (photo/gender/nationality hidden where avoid/none); focus order only with 2+ places; KSA still looks like v5. Screenshots, look at them. Report real problems only.`, { label: 'review-ux', phase: 'Review', schema: RS }),
  () => agent(`${BRIEF}\n\nBuilder report:\n${built}\n\nREVIEWER 2 — code + regressions. Read the builder's patches/js/css. Build to ${SCR}/rev2.html. Check: every patch 'old' is unique and minimal; no other screens broken (go() through every .scr in the jump menu for SA and GB, collect page errors); settings mode of profile (pfMode) still works from prefs; jump menu has the new screens; language switch + MKT.set re-render your screens; no hard-coded copy or currency; no globals clobbered; RTL layout of new screens. Report real problems only.`, { label: 'review-code', phase: 'Review', schema: RS }),
  () => agent(`${BRIEF}\n\nBuilder report:\n${built}\n\nREVIEWER 3 — copy. Read the ob6 keys in all four newkeys files. Check EN is crisp and consistent with v5's voice; Gulf Arabic matches v5's register; neutral Arabic is formal-leaning white Arabic with no Gulf dialect; French is natural, vouvoiement; gender tokens used where the user/persona is gendered (AR/FR); tokens identical across languages; glossary terms respected. Give concrete replacement strings. Report real problems only.`, { label: 'review-copy', phase: 'Review', schema: RS }),
])
const findings = reviews.filter(Boolean).flatMap(r => r.findings)
log(`${findings.length} findings`)
